#!/usr/bin/env bash
#
# Removes everything generated by installs and builds, so that the next
# `npm install` (and `pod install` / Gradle build) starts from scratch.
#
# Usage: ./clean.sh [--lock] [--caches] [--dry-run]
#   --lock     also delete package-lock.json and ios/Podfile.lock files
#   --caches   also clear Metro/Haste temp caches and run `watchman watch-del-all`
#   --dry-run  only print what would be removed
#
# Applies to the repo root and to any nested project (e.g. an example app)
# that has its own package.json, ios/ or android/ folder.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$ROOT"

REMOVE_LOCK=false
CLEAR_CACHES=false
DRY_RUN=false

for arg in "$@"; do
  case "$arg" in
    --lock) REMOVE_LOCK=true ;;
    --caches) CLEAR_CACHES=true ;;
    --dry-run) DRY_RUN=true ;;
    -h|--help)
      sed -n '2,13p' "$0" | sed 's/^# \{0,1\}//'
      exit 0
      ;;
    *)
      echo "Unknown option: $arg (see ./clean.sh --help)" >&2
      exit 1
      ;;
  esac
done

remove() {
  local path
  for path in "$@"; do
    [ -e "$path" ] || [ -L "$path" ] || continue
    echo "  removing ${path#"$ROOT"/}"
    if [ "$DRY_RUN" = false ]; then
      rm -rf "$path"
    fi
  done
}

# Every directory holding a package.json, ios/ or android/ (outside node_modules and .git).
project_dirs() {
  find "$ROOT" \
    \( -name node_modules -o -name .git -o -name Pods -o -name build \) -prune -o \
    \( -name package.json -o -name ios -o -name android \) -print 2>/dev/null |
    while read -r match; do
      case "$(basename "$match")" in
        package.json) dirname "$match" ;;
        *) [ -d "$match" ] && dirname "$match" ;;
      esac
    done | sort -u
}

clean_js() {
  local dir="$1"
  remove \
    "$dir/node_modules" \
    "$dir/dist" \
    "$dir/build" \
    "$dir/coverage" \
    "$dir/.nyc_output" \
    "$dir/.expo" \
    "$dir/.expo-shared" \
    "$dir/.cache" \
    "$dir/.parcel-cache" \
    "$dir/.eslintcache" \
    "$dir/web-build"
  find "$dir" -maxdepth 1 \( -name '*.tsbuildinfo' -o -name '*.tgz' -o -name 'npm-debug.log*' -o -name 'yarn-error.log*' \) \
    -print 2>/dev/null | while read -r f; do remove "$f"; done
  if [ "$REMOVE_LOCK" = true ]; then
    remove "$dir/package-lock.json" "$dir/yarn.lock" "$dir/pnpm-lock.yaml"
  fi
}

clean_ios() {
  local ios="$1/ios"
  [ -d "$ios" ] || return 0
  remove \
    "$ios/Pods" \
    "$ios/build" \
    "$ios/DerivedData" \
    "$ios/.xcode.env.local"
  find "$ios" -maxdepth 2 -name xcuserdata -type d -print 2>/dev/null |
    while read -r d; do remove "$d"; done
  if [ "$REMOVE_LOCK" = true ]; then
    remove "$ios/Podfile.lock"
  fi
}

clean_android() {
  local android="$1/android"
  [ -d "$android" ] || return 0
  remove \
    "$android/.gradle" \
    "$android/.kotlin" \
    "$android/.idea" \
    "$android/build" \
    "$android/local.properties" \
    "$android/captures"
  # Per-module build/, .cxx/ and generated codegen output (app/, plus any library modules).
  find "$android" -mindepth 2 -maxdepth 3 \( -name build -o -name .cxx -o -name .externalNativeBuild \) -type d \
    -not -path '*/src/*' -print 2>/dev/null |
    while read -r d; do remove "$d"; done
}

[ "$DRY_RUN" = true ] && echo "Dry run: nothing will be deleted."

project_dirs | while read -r dir; do
  if [ "$dir" = "$ROOT" ]; then echo "Cleaning repo root"; else echo "Cleaning ${dir#"$ROOT"/}"; fi
  clean_js "$dir"
  clean_ios "$dir"
  clean_android "$dir"
done

if [ "$CLEAR_CACHES" = true ]; then
  echo "Clearing Metro / Haste caches"
  TMP="${TMPDIR:-/tmp}"; TMP="${TMP%/}"
  for c in "$TMP"/metro-* "$TMP"/haste-map-* "$TMP"/react-native-packager-cache-*; do
    remove "$c"
  done
  if command -v watchman >/dev/null 2>&1; then
    echo "  watchman watch-del-all"
    [ "$DRY_RUN" = false ] && watchman watch-del-all >/dev/null 2>&1 || true
  fi
fi

echo "Done. Run 'npm install' to reinstall dependencies."
